import type { WriteFileOptions } from '@capacitor/filesystem'
import { Directory, Filesystem } from '@capacitor/filesystem'
import axios from 'axios'
import { FileOpener } from '@capawesome-team/capacitor-file-opener'

export async function downloadFiles(url: string, needOpen: boolean = true) {
  try {
    console.debug(`download file url: ${url}`)
    const file = await axios.get(url, { responseType: 'blob' })
    const blob = file.data
    let path = url.split('/').pop()
    path = path?.split('?')[0] as string
    console.debug(`download file path: ${path}`)
    const base64 = await convertBlobToBase64(blob as Blob) as string
    const options: WriteFileOptions = {
      path,
      data: base64,
      directory: Directory.External,
    }
    const write = await Filesystem.writeFile(options)
    console.debug('Write File:', write)
    const uri = write.uri
    if (needOpen) {
      openLocalFile(uri)
    }
    return uri
  }
  catch (err) {
    console.debug('Error Downloading File:')
    console.debug(err)
  }
  finally {
    Filesystem.removeAllListeners()
  }
}

export async function handleFilesystemPermissions() {
  try {
    const hasPermission = await Filesystem.checkPermissions()
    if (hasPermission.publicStorage === 'granted') {
      return true
    }
    else {
      const permission = await Filesystem.requestPermissions()
      console.debug('Permission:', permission)
      return permission.publicStorage === 'granted'
    }
  }
  catch (err) {
    console.error('Error Requesting Permissions:')
    console.error(err)
  }
}

export async function getLocalFile(url: string) {
  try {
    let path = url.split('/').pop()
    path = path?.split('?')[0] as string
    const file = await Filesystem.readFile({
      path,
      directory: Directory.External,
    })
    // return image base64
    return `data:image/png;base64,${file.data}`
  }
  catch (err) {
    console.error('Error Reading File:')
    console.error(err)
  }
}

function convertBlobToBase64(blob: Blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onerror = reject
    reader.onload = () => {
      resolve(reader.result)
    }
    reader.readAsDataURL(blob)
  })
}

export async function openLocalFile(uri: string) {
  try {
    await FileOpener.openFile({
      path: uri,
    })
  }
  catch (err) {
    console.error('Error Opening File:')
    console.error(err)
  }
}

export async function deleteFile(url: string) {
  try {
    let path = url.split('/').pop()
    path = path?.split('?')[0] as string
    await Filesystem.deleteFile({
      path,
      directory: Directory.ExternalStorage,
    })
  }
  catch (err) {
    console.error('Error Deleting File:')
    console.error(err)
  }
}
