<script setup lang="ts">
import { nextTick, onMounted, ref } from 'vue'
import {
  IonButton,
  IonContent,
  IonModal,
  IonPage,
  useIonRouter,
} from '@ionic/vue'
import domtoimage from 'dom-to-image'
import { SafeArea } from 'capacitor-plugin-safe-area'
import { Capacitor } from '@capacitor/core'
import CharacterPose from './chat/CharacterPose.vue'
import type { Message, SpritePosition } from '@/types'
import { videoEndingImage } from '@/assets/VideoEndingBase64'
import CheckedIconCircleFill from '@/components/svg/CheckedIconCircleFill.vue'
import CheckIconCircleEmpty from '@/components/svg/CheckIconCircleEmpty.vue'
import CheckIconFilled from '@/components/svg/CheckIconFilled.vue'
import CloseIcon from '@/components/svg/CloseIcon.vue'
import MessageRow from '@/components/MessageRow.vue'
import CircleProgress from '@/components/CircleProgress.vue'
import ShareWatermark from '@/components/ShareWatermark.vue'
import PovTitle from '@/components/PovTitle.vue'
import { chatService } from '@/services/chat'
import { useShareStore } from '@/store/shareStore'
import { useToastStore } from '@/store/toast'
import { sleep } from '@/utils/baseUtil'
import { getAvatarsPosition } from '@/utils/poseUtil'
import { deleteFile, downloadFiles, getLocalFile, handleFilesystemPermissions, openLocalFile } from '@/utils/fileUtil'

const router = useIonRouter()
const shareStore = useShareStore()
const toastStore = useToastStore()
const { chat, messages } = shareStore
const selectedIndexs = ref<number[]>([])

const selectedMessages = ref<Message[]>([])
const avatarPositions = ref<(SpritePosition | undefined)[]>([])
const currentIndex = ref(0)

const creatingVideo = ref(false)
const images = ref<Blob[]>([])
const pngImages = ref<string[]>([])
const completeGenerateImages = ref(false)
const progress = ref(0)
const timer = ref<NodeJS.Timeout>()

const bgUrl = ref(chat?.universe.events[0]?.gifUrl)
const fileUri = ref<string>()

onMounted(() => {
  handleFilesystemPermissions()
  if (!chat) {
    router.back()
  }
})

function onToggleMessage(index: number) {
  if (selectedIndexs.value.includes(index)) {
    selectedIndexs.value = selectedIndexs.value.filter(i => i !== index)
  }
  else {
    if (selectedIndexs.value.length >= 10) {
      toastStore.setToast('You can only select up to 10 messages')
      return
    }
    selectedIndexs.value = [...selectedIndexs.value, index]
  }
}

async function startCreateVideo() {
  if (selectedIndexs.value.length === 0) {
    toastStore.setToast('Please select at least one message')
    return
  }
  // generate selected messages
  selectedMessages.value = messages.filter((_, index) =>
    selectedIndexs.value.includes(index),
  )
  // generate avatar position according to messages
  const positions: (SpritePosition | undefined)[] = []
  selectedMessages.value.forEach((m, index) => {
    const newAvatarPosition = getAvatarsPosition(
      m,
      index === 0 ? undefined : positions[index - 1],
    )
    positions.push(newAvatarPosition)
  })
  avatarPositions.value = positions
  creatingVideo.value = true

  await nextTick()

  // upload images
  try {
    // start to run dom to canvas one by one and upload image to server waiting for generating video
    // wait until all images are converted
    for (let i = 0; i < selectedMessages.value.length; i++) {
      currentIndex.value = i
      await nextTick()
      // 前50%的进度条根据生成图片的速度控制
      progress.value = (i + 1) / selectedMessages.value.length / 2
      await convertDomToImage()
    }
    console.debug(pngImages.value)
    // 这里开始做一个timer来模拟视频生成的进度，大概每秒增加2%的进度
    timer.value = setInterval(() => {
      progress.value += 0.02
      if (progress.value >= 0.76) {
        clearInterval(timer.value)
      }
    }, 1000)

    // convert the asset VideoEndingImage to base64
    const files = [...pngImages.value, videoEndingImage]
    const segmentDuration = [
      ...selectedMessages.value.map((m) => {
        if (m.audioUrl && m.audioUrl.length > 0) {
          return m.audioUrl
        }
        else {
          return '3.0'
        }
      }),
      '1.0',
    ]
    const videoUrl = (await chatService.createVideo(
      files,
      segmentDuration,
      chat?.bgmUrl || '',
    )) as string
    // 这里清空上面的timer，然后模拟下载视频的进度
    clearInterval(timer.value)
    // 下载文件
    fileUri.value = Capacitor.isNativePlatform() ? await downloadFiles(videoUrl, false) : videoUrl
    progress.value = 0.95
    // save the videoUrl to gallery
    progress.value = 1
    completeGenerateImages.value = true
    // 清理刚刚下载过的图片，保留视频
    await deleteCache()
  }
  catch (err) {
    console.error(err)
    creatingVideo.value = false
    toastStore.setToast('Failed to create video')
    reset()
  }
}
async function convertDomToImage() {
  console.group(`convertDomToImage: ${currentIndex.value}`)
  const node = document.getElementById('video-creation-node')
  if (Capacitor.isNativePlatform()) {
    await handleUrlImage()
  }
  try {
    const safeInsets = await SafeArea.getSafeAreaInsets()
    await domtoimage.toPng(node, {
      width: window.innerWidth,
      height:
        window.innerHeight - safeInsets.insets.top - safeInsets.insets.bottom,
    })
    await domtoimage.toPng(node, {
      width: window.innerWidth,
      height:
        window.innerHeight - safeInsets.insets.top - safeInsets.insets.bottom,
    })
    const png = (await domtoimage.toPng(node, {
      width: window.innerWidth,
      height:
        window.innerHeight - safeInsets.insets.top - safeInsets.insets.bottom,
    })) as string
    pngImages.value.push(png)
  }
  catch (err) {
    console.error(err)
    console.groupEnd()
    throw err
  }
  console.groupEnd()
}

async function handleUrlImage() {
  // make sure the background image is loaded
  const bg = chat!.universe.events[0]?.gifUrl
  if (bg) {
    bgUrl.value = await replaceUrlToLocalfile(bg)
  }

  const avatarPosition = avatarPositions.value[currentIndex.value]
  if (avatarPosition) {
    const leftAvatar = avatarPosition.left?.url
    const rightAvatar = avatarPosition.right?.url
    const middleAvatar = avatarPosition.middle?.url
    if (leftAvatar) {
      avatarPosition.left!.url = await replaceUrlToLocalfile(leftAvatar)
    }

    if (rightAvatar) {
      avatarPosition.right!.url = await replaceUrlToLocalfile(rightAvatar)
    }

    if (middleAvatar) {
      avatarPosition.middle!.url = await replaceUrlToLocalfile(middleAvatar)
    }
  }
  avatarPositions.value[currentIndex.value] = avatarPosition
  await nextTick()
}

async function replaceUrlToLocalfile(url: string) {
  if (Capacitor.isNativePlatform()) {
    const localUri = await downloadFiles(url, false)
    if (localUri) {
      return await getLocalFile(url)
    }
  }
  else {
    await sleep(200)
  }
}

function openVideo() {
  if (fileUri.value) {
    if (Capacitor.isNativePlatform()) {
      openLocalFile(fileUri.value)
    }
    else {
      window.open(fileUri.value, '_blank')
    }
  }
  else {
    toastStore.setToast('Failed to open video, please regenerate')
  }
}

function reset() {
  selectedIndexs.value = []
  selectedMessages.value = []
  avatarPositions.value = []
  currentIndex.value = 0
  creatingVideo.value = false
  images.value = []
  pngImages.value = []
  completeGenerateImages.value = false
  progress.value = 0
  clearInterval(timer.value)
  timer.value = undefined
  router.back()
}

async function deleteCache() {
  if (!Capacitor.isNativePlatform()) {
    return
  }
  // delete bg
  if (chat?.universe.events[0]?.gifUrl) {
    await deleteFile(chat?.universe.events[0]?.gifUrl)
  }

  // delete all avatars in messages poseUrl
  const filesToDelete = selectedMessages.value.map((m) => {
    if (m.poseUrl && m.poseUrl.length > 0) {
      return m.poseUrl
    }
    else {
      return null
    }
  }).filter(f => f !== null) as string[]

  for (const file of filesToDelete) {
    await deleteFile(file)
  }
}
</script>

<template>
  <ion-page>
    <div
      class="flex-shrink-0 w-full pt-unsafe-area pb-3 flex flex-col gap-4 absolute top-0 left-0 page-header z-200"
    >
      <div class="h-12 pl-1 pr-4 flex items-center justify-between">
        <ion-button
          fill="clear"
          size="small"
          router-direction="back"
          @click="
            () => {
              shareStore.reset();
              router.back();
            }
          "
        >
          <close-icon />
        </ion-button>
        <p class="text-on-bg-1 text-5 fw-700 leading-6">
          Share Sekai
        </p>
        <div class="w-4 h-4" />
      </div>
    </div>
    <ion-content
      v-if="chat !== null || !creatingVideo"
      :style="{
        '--background': `url('${chat!.universe.events[0]?.gifUrl || ''}') no-repeat center center / cover`,
      }"
    >
      <div
        v-if="!creatingVideo"
        class="flex flex-col justify-end gap-2 px-4 mt-24 pt-unsafe-area pb-unsafe-area mb-20"
      >
        <div
          v-for="(message, index) in messages"
          :key="message.messageId"
          class="flex items-center justify-between gap-3"
          @click="onToggleMessage(index)"
        >
          <checked-icon-circle-fill v-if="selectedIndexs.includes(index)" />
          <check-icon-circle-empty v-else />
          <message-row
            :chat-id="`${chat!.chatId}-share`"
            :message="message"
            :readonly="true"
          />
        </div>
      </div>
    </ion-content>
    <div
      v-if="creatingVideo && chat != null"
      id="video-creation-node"
      class="h-full w-full px-4"
    >
      <img
        :src="`${bgUrl}`"
        class="absolute w-full h-full left-0 top-0"
      >
      <character-pose
        :key="`character-pose-${chat!.chatId}`"
        :positions="avatarPositions"
        :current-index="currentIndex"
      />
      <div
        class="relative flex flex-col justify-end gap-4 z-100 pt-unsafe-area pb-unsafe-area mb-20"
        :style="{ height: `calc(100% - ${135}px)` }"
      >
        <message-row
          :chat-id="`${chat!.chatId}-share`"
          :message="selectedMessages[currentIndex]"
          :readonly="true"
        />
      </div>
      <pov-title
        v-if="chat!.universe.highlight.text"
        :key="`pov-title-${chat!.chatId}-share`"
        :text="chat!.universe.highlight.text"
        :width="chat!.universe.highlight.width"
        :height="chat!.universe.highlight.height"
        :x="chat!.universe.highlight.x"
        :y="chat!.universe.highlight.y"
      />
      <share-watermark />
    </div>
    <div
      v-if="!creatingVideo"
      class="flex justify-between items-center gradient-bg px-4 py-2.5 fixed bottom-0 w-full z-100"
    >
      <p class="text-white text-3.5 leading-normal">
        {{ selectedIndexs.length }} messages selected
      </p>
      <button class="btn-primary max-w-[191px]" @click="startCreateVideo">
        Create Video
      </button>
    </div>
    <ion-modal
      id="creating-video-modal"
      :is-open="creatingVideo"
      @did-dismiss="reset"
    >
      <div
        v-if="!completeGenerateImages"
        class="flex flex-col items-center justify-center p-4 gap-4"
      >
        <p class="text-white text-3.5 leading-normal color-#B8B8B8">
          Generating Video... Please wait...
        </p>
        <circle-progress :prop-progress="progress" />
        <ion-button fill="clear" class="color-#B8B8B8" @click="reset">
          Cancel
        </ion-button>
      </div>
      <div v-else class="flex flex-col items-center justify-center p-4 gap-2">
        <check-icon-filled />
        <h4 class="color-#fff leading-normal text-4.5">
          Video is ready to share
        </h4>
        <p class="text-3.5 leading-normal color-#B8B8B8 text-center pb-2">
          Tap the button in the bottom left corner <br> to save or share your video
        </p>
        <button
          class="btn-primary" @click="openVideo"
        >
          Share Video
        </button>
        <button
          class="btn-inverse" @click="() => {
            creatingVideo = false;
            reset();
          }"
        >
          Cancel
        </button>
      </div>
    </ion-modal>
  </ion-page>
</template>

<style scoped>
.gradient-bg {
  background: linear-gradient(
    180deg,
    rgba(47, 47, 47, 0.35) 0%,
    rgba(47, 47, 47, 0.35) 27.85%,
    rgba(47, 47, 47, 0.35) 100%
  );
}
